 import { useState, useEffect, useCallback } from 'react'

// Import all translation files
import en from '../locales/en.json'
import zu from '../locales/zu.json'
import xh from '../locales/xh.json'
import af from '../locales/af.json'
import nso from '../locales/nso.json'
import tn from '../locales/tn.json'
import st from '../locales/st.json'
import ts from '../locales/ts.json'
import ss from '../locales/ss.json'
import ve from '../locales/ve.json'
import nr from '../locales/nr.json'
import es from '../locales/es.json'
import fr from '../locales/fr.json'
import de from '../locales/de.json'
import pt from '../locales/pt.json'
import it from '../locales/it.json'
import nl from '../locales/nl.json'

// Map language codes to translations
const translationsMap = {
  en,
  zu,
  xh,
  af,
  nso,
  tn,
  st,
  ts,
  ss,
  ve,
  nr,
  es,
  fr,
  de,
  pt,
  it,
  nl
}

export function useTranslation() {
  const [language, setLanguage] = useState(() => {
    return localStorage.getItem('language') || 'en'
  })
  const [translations, setTranslations] = useState(translationsMap.en)
  const [loading, setLoading] = useState(false)

  // Load translations when language changes
  useEffect(() => {
    setLoading(true)
    try {
      const newTranslations = translationsMap[language] || translationsMap.en
      setTranslations(newTranslations)
      // Save to localStorage
      localStorage.setItem('language', language)
    } catch (error) {
      console.error('Error loading translations:', error)
      setTranslations(translationsMap.en)
    } finally {
      setLoading(false)
    }
  }, [language])

  // Helper function to get translation with fallback
  const t = useCallback((key) => {
    if (!key) return key
    // Check if translation exists in current language
    if (translations && translations[key] !== undefined) {
      return translations[key]
    }
    // Fallback to English
    if (translationsMap.en && translationsMap.en[key] !== undefined) {
      return translationsMap.en[key]
    }
    // Return the key itself as last resort
    return key
  }, [translations])

  const changeLanguage = useCallback((newLanguage) => {
    if (translationsMap[newLanguage]) {
      setLanguage(newLanguage)
      localStorage.setItem('language', newLanguage)
      // Dispatch a custom event so other components can react
      window.dispatchEvent(new CustomEvent('languageChanged', { detail: newLanguage }))
    }
  }, [])

  return { 
    t, 
    language, 
    setLanguage: changeLanguage, 
    loading,
    translations
  }
}
